import { Encoder, Utils } from '@everyboard/lib';
import { Direction, DirectionFactory } from './Direction';
/**
 * Ordinal as in both orthogonal and diagonal
 */
export class Ordinal extends Direction {
    static UP = new Ordinal(0, -1);
    static UP_RIGHT = new Ordinal(1, -1);
    static RIGHT = new Ordinal(1, 0);
    static DOWN_RIGHT = new Ordinal(1, 1);
    static DOWN = new Ordinal(0, 1);
    static DOWN_LEFT = new Ordinal(-1, 1);
    static LEFT = new Ordinal(-1, 0);
    static UP_LEFT = new Ordinal(-1, -1);
    static factory = new class extends DirectionFactory {
        all = [
            Ordinal.RIGHT,
            Ordinal.DOWN_RIGHT,
            Ordinal.DOWN,
            Ordinal.DOWN_LEFT,
            Ordinal.LEFT,
            Ordinal.UP_LEFT,
            Ordinal.UP,
            Ordinal.UP_RIGHT,
        ];
    };
    static ORDINALS = Ordinal.factory.all;
    static DIAGONALS = [
        Ordinal.UP_RIGHT,
        Ordinal.DOWN_RIGHT,
        Ordinal.DOWN_LEFT,
        Ordinal.UP_LEFT,
    ];
    static ORTHOGONALS = [
        Ordinal.UP,
        Ordinal.RIGHT,
        Ordinal.DOWN,
        Ordinal.LEFT,
    ];
    static encoder = Encoder.fromFunctions((dir) => {
        return dir.toString();
    }, (encoded) => {
        Utils.assert(typeof encoded === 'string', 'Invalid encoded direction');
        const fromString = Ordinal.factory.fromString(encoded);
        return fromString.get();
    });
    getAngle() {
        switch (this) {
            case Ordinal.RIGHT: return 0;
            case Ordinal.DOWN_RIGHT: return 45;
            case Ordinal.DOWN: return 90;
            case Ordinal.DOWN_LEFT: return 135;
            case Ordinal.LEFT: return 180;
            case Ordinal.UP_LEFT: return 225;
            case Ordinal.UP: return 270;
            default:
                Utils.expectToBe(this, Ordinal.UP_RIGHT);
                return 315;
        }
    }
    getOpposite() {
        const opposite = Ordinal.factory.from(-this.x, -this.y);
        return opposite.get();
    }
}
