import { Set } from '@everyboard/lib';
import { Coord } from './Coord';
export class GobanUtils {
    static getHoshis(width, height) {
        let hoshis = new Set();
        if (width < 5 || height < 5) {
            return [];
        }
        const horizontalMiddle = GobanUtils.getHorizontalCenter(width);
        const verticalMiddle = GobanUtils.getVerticalCenter(height);
        const left = GobanUtils.getHorizontalLeft(width);
        const up = GobanUtils.getVerticalUp(height);
        const right = GobanUtils.getHorizontalRight(width);
        const down = GobanUtils.getVerticalDown(height);
        if (12 < height && height % 2 === 1) {
            hoshis = hoshis
                .addElement(new Coord(left, verticalMiddle))
                .addElement(new Coord(right, verticalMiddle));
        }
        if (12 < width && width % 2 === 1) {
            hoshis = hoshis
                .addElement(new Coord(horizontalMiddle, up))
                .addElement(new Coord(horizontalMiddle, down));
        }
        if (width % 2 === 1 && height % 2 === 1) {
            hoshis = hoshis.addElement(new Coord(horizontalMiddle, verticalMiddle));
        }
        hoshis = hoshis
            .addElement(new Coord(left, up))
            .addElement(new Coord(left, down))
            .addElement(new Coord(right, up))
            .addElement(new Coord(right, down));
        return hoshis.toList();
    }
    static getHorizontalLeft(width) {
        return width < 12 ? 2 : 3;
    }
    static getHorizontalCenter(width) {
        return Math.floor(width / 2);
    }
    static getHorizontalRight(width) {
        const left = GobanUtils.getHorizontalLeft(width);
        return width - (left + 1);
    }
    static getVerticalUp(height) {
        return height < 12 ? 2 : 3;
    }
    static getVerticalCenter(height) {
        return Math.floor(height / 2);
    }
    static getVerticalDown(height) {
        const up = GobanUtils.getVerticalUp(height);
        return height - (up + 1);
    }
}
