import { MGPOptional } from '@everyboard/lib';
import { HexaDirection } from './HexaDirection';
export class HexaLine {
    offset;
    constant;
    static fromTwoCoords(coord1, coord2) {
        // Finds the line from the cube coordinates
        const x1 = coord1.x;
        const x2 = coord2.x;
        const y1 = coord1.y;
        const y2 = coord2.y;
        const s1 = x1 + y1;
        const s2 = x2 + y2;
        if (x1 === x2 && y1 !== y2 && s1 !== s2)
            return MGPOptional.of(HexaLine.constantQ(x1));
        if (x1 !== x2 && y1 === y2 && s1 !== s2)
            return MGPOptional.of(HexaLine.constantR(y1));
        if (x1 !== x2 && y1 !== y2 && s1 === s2)
            return MGPOptional.of(HexaLine.constantS(s1));
        return MGPOptional.empty();
    }
    static constantQ(offset) {
        return new HexaLine(offset, 'q');
    }
    static constantR(offset) {
        return new HexaLine(offset, 'r');
    }
    static constantS(offset) {
        return new HexaLine(offset, 's');
    }
    static areOnSameLine(coords) {
        if (coords.length < 2)
            return true;
        const lineOpt = HexaLine.fromTwoCoords(coords[0], coords[1]);
        if (lineOpt.isAbsent())
            return false;
        const line = lineOpt.get();
        for (const coord of coords.slice(2)) {
            if (line.contains(coord) === false)
                return false;
        }
        return true;
    }
    constructor(offset, constant) {
        this.offset = offset;
        this.constant = constant;
    }
    toString() {
        return `Line(${this.constant}, ${this.offset})`;
    }
    equals(other) {
        if (this === other)
            return true;
        if (this.offset !== other.offset)
            return false;
        if (this.constant !== other.constant)
            return false;
        return true;
    }
    contains(coord) {
        switch (this.constant) {
            case 'q':
                return coord.x === this.offset;
            case 'r':
                return coord.y === this.offset;
            case 's':
                return coord.x + coord.y === this.offset;
        }
    }
    getDirection() {
        switch (this.constant) {
            case 'q':
                return HexaDirection.DOWN;
            case 'r':
                return HexaDirection.RIGHT;
            case 's':
                return HexaDirection.DOWN_LEFT;
        }
    }
}
