import { BoardValue } from './AI/BoardValue';
import { Player, PlayerOrNone } from './Player';
export class GameStatus {
    isEndGame;
    winner;
    static ZERO_WON = new GameStatus(true, Player.ZERO);
    static ONE_WON = new GameStatus(true, Player.ONE);
    static DRAW = new GameStatus(true, PlayerOrNone.NONE);
    static ONGOING = new GameStatus(false, PlayerOrNone.NONE);
    static getVictory(player) {
        if (player === Player.ZERO) {
            return GameStatus.ZERO_WON;
        }
        else {
            return GameStatus.ONE_WON;
        }
    }
    static getDefeat(player) {
        if (player === Player.ZERO) {
            return GameStatus.ONE_WON;
        }
        else {
            return GameStatus.ZERO_WON;
        }
    }
    constructor(isEndGame, winner) {
        this.isEndGame = isEndGame;
        this.winner = winner;
    }
    toBoardValue() {
        if (this.winner.isPlayer()) {
            return BoardValue.of(BoardValue.getVictoryValueOf(this.winner));
        }
        else {
            return BoardValue.of(0);
        }
    }
}
