import { MGPOptional } from './MGPOptional';
export function isJSONPrimitive(value) {
    if (typeof value === 'string')
        return true;
    if (typeof value === 'number')
        return true;
    if (typeof value === 'boolean')
        return true;
    if (value === null)
        return true; // null if of type 'object', so we check for equality instead
    return false;
}
export class JSONParser {
    static toJSONValue(v) {
        if (isJSONPrimitive(v))
            return v;
        if (Array.isArray(v)) {
            const array = [];
            for (const item of v) {
                array.push(JSONParser.toJSONValueWithoutArray(item));
            }
            return array;
        }
        else {
            // The only type left is "object", because we know it's coming from JSON.parse
            return JSONParser.toJSONObject(v);
        }
    }
    static toJSONObject(v) {
        const obj = {};
        for (const [key, value] of Object.entries(v)) {
            obj[key] = JSONParser.toJSONValue(value);
        }
        return obj;
    }
    static toJSONValueWithoutArray(v) {
        if (isJSONPrimitive(v))
            return v;
        if (Array.isArray(v)) {
            throw Error(`this is array contained in another array, which is forbidden: ${v}`);
        }
        else {
            return JSONParser.toJSONObject(v);
        }
    }
    // Try to parse a JSONValue and to return it. Fails with MGPOptional.empty otherwise.
    static parseJSONSafely(json) {
        try {
            return MGPOptional.of(JSONParser.toJSONValue(JSON.parse(json)));
        }
        catch {
            return MGPOptional.empty();
        }
    }
}
