import { Player } from '../Player';
export class GameState {
    turn;
    constructor(turn) {
        this.turn = turn;
    }
    getCurrentPlayer() {
        return Player.ofTurn(this.turn);
    }
    getPreviousOpponent() {
        return this.getCurrentPlayer();
    }
    getCurrentOpponent() {
        return this.turn % 2 === 1 ? Player.ZERO : Player.ONE;
    }
    getPreviousPlayer() {
        return this.getCurrentOpponent();
    }
}
