import { FourStatePiece } from '../FourStatePiece';
import { GameStateWithTable } from './GameStateWithTable';
export class FourStatePieceGameStateWithTable extends GameStateWithTable {
    getPlayerCoordsAndContent() {
        return this
            .getCoordsAndContents()
            .filter((value) => {
            return value.content.isPlayer();
        })
            .map((value) => {
            return {
                coord: value.coord,
                content: value.content.getPlayer(),
            };
        });
    }
    isPlayerAt(coord) {
        const piece = this.getPieceAt(coord);
        return piece.isPlayer();
    }
    hasPieceBelongingTo(coord, player) {
        const optional = this.getOptionalPieceAt(coord);
        if (optional.isPresent()) {
            return optional.get().is(player);
        }
        else {
            return false;
        }
    }
    coordIsOccupiedSquare(coord) {
        const optional = this.getOptionalPieceAt(coord);
        if (optional.isPresent()) {
            return optional.get().isPlayer();
        }
        else {
            return false;
        }
    }
    isOnBoard(coord) {
        if (super.isOnBoard(coord)) {
            return this.getUnsafe(coord) !== FourStatePiece.UNREACHABLE;
        }
        else {
            return false;
        }
    }
    static of(oldState, newBoard) {
        return new FourStatePieceGameStateWithTable(newBoard, oldState.turn);
    }
    incrementTurn() {
        return new FourStatePieceGameStateWithTable(this.getCopiedBoard(), this.turn + 1);
    }
    setPieceAt(coord, value) {
        return GameStateWithTable.setPieceAt(this, coord, value, FourStatePieceGameStateWithTable.of);
    }
}
