import { Encoder, Utils } from '@everyboard/lib';
import { Direction, DirectionFactory } from './Direction';
import { Ordinal } from './Ordinal';
export class Orthogonal extends Direction {
    static UP = new Orthogonal(0, -1);
    static RIGHT = new Orthogonal(1, 0);
    static DOWN = new Orthogonal(0, 1);
    static LEFT = new Orthogonal(-1, 0);
    static factory = new class extends DirectionFactory {
        all = [
            Orthogonal.RIGHT,
            Orthogonal.DOWN,
            Orthogonal.LEFT,
            Orthogonal.UP,
        ];
    };
    static ORTHOGONALS = Orthogonal.factory.all;
    static encoder = Encoder.fromFunctions((dir) => {
        return dir.toString();
    }, (encoded) => {
        Utils.assert(typeof encoded === 'string', 'Invalid encoded orthogonal');
        const fromString = Orthogonal.factory.fromString(encoded);
        return fromString.get();
    });
    getOpposite() {
        const opposite = Orthogonal.factory.from(-this.x, -this.y);
        return opposite.get();
    }
    rotateClockwise() {
        const rotated = Orthogonal.factory.from(-this.y, this.x);
        return rotated.get();
    }
    toOrdinal() {
        switch (this) {
            case Orthogonal.UP: return Ordinal.UP;
            case Orthogonal.RIGHT: return Ordinal.RIGHT;
            case Orthogonal.DOWN: return Ordinal.DOWN;
            default:
                Utils.expectToBe(this, Orthogonal.LEFT);
                return Ordinal.LEFT;
        }
    }
    getAngle() {
        return this.toOrdinal().getAngle();
    }
}
