import { Utils } from '@everyboard/lib';
import { Player, PlayerOrNone } from './Player';
export class FourStatePiece {
    player;
    reachable;
    static ZERO = new FourStatePiece(Player.ZERO, true);
    static ONE = new FourStatePiece(Player.ONE, true);
    static EMPTY = new FourStatePiece(PlayerOrNone.NONE, true);
    static UNREACHABLE = new FourStatePiece(PlayerOrNone.NONE, false);
    static ofPlayer(player) {
        switch (player) {
            case Player.ZERO: return FourStatePiece.ZERO;
            default:
                Utils.expectToBe(player, Player.ONE);
                return FourStatePiece.ONE;
        }
    }
    constructor(player, reachable) {
        this.player = player;
        this.reachable = reachable;
    }
    equals(other) {
        return this.player.equals(other.player) &&
            this.reachable === other.reachable;
    }
    is(player) {
        return this.player === player;
    }
    isPlayer() {
        return this === FourStatePiece.ZERO || this === FourStatePiece.ONE;
    }
    isReachable() {
        return this.reachable;
    }
    getPlayer() {
        return this.player;
    }
}
